using ExpenseFlow.Application.Abstractions;
using ExpenseFlow.Application.Common;
using ExpenseFlow.Domain.Common;
using ExpenseFlow.Domain.Entities;
using ExpenseFlow.Domain.Enums;
using FluentValidation;
using MediatR;
using Microsoft.EntityFrameworkCore;

namespace ExpenseFlow.Application.Features.Expenses;

/// <param name="Id">Generated by the app, so a retry never creates a duplicate.</param>
public record SubmitExpenseCommand(
    Guid Id, decimal Amount, string Currency, ExpenseCategory Category, string? Description,
    DateOnly ExpenseDate, string ReceiptBlobName) : IRequest<ExpenseSummaryDto>;

public sealed class SubmitExpenseValidator : AbstractValidator<SubmitExpenseCommand>
{
    public SubmitExpenseValidator()
    {
        RuleFor(x => x.Id).NotEmpty();
        RuleFor(x => x.Amount).GreaterThan(0).LessThanOrEqualTo(Expense.MaxAmount)
            .PrecisionScale(12, 2, ignoreTrailingZeros: true);
        RuleFor(x => x.Currency).NotEmpty().Matches("^[A-Za-z]{3}$");
        RuleFor(x => x.Category).IsInEnum();
        RuleFor(x => x.Description).MaximumLength(Expense.MaxDescriptionLength);
        RuleFor(x => x.ExpenseDate).NotEmpty();
        RuleFor(x => x.ReceiptBlobName).NotEmpty().MaximumLength(300);
    }
}

public sealed class SubmitExpenseHandler(
    IAppDbContext db, ICurrentUser currentUser, IClock clock, IReceiptStorage receipts, IWorkflowService workflows)
    : IRequestHandler<SubmitExpenseCommand, ExpenseSummaryDto>
{
    public async Task<ExpenseSummaryDto> Handle(SubmitExpenseCommand cmd, CancellationToken ct)
    {
        var userId = currentUser.UserId;

        // Idempotency: the same id sent again (retry, double tap) returns the existing expense.
        var expense = await db.Expenses.FirstOrDefaultAsync(e => e.Id == cmd.Id, ct);
        if (expense is not null)
        {
            if (expense.EmployeeId != userId) throw new ConflictException("This expense id is already used.");
        }
        else
        {
            if (!cmd.ReceiptBlobName.StartsWith($"receipts/{userId}/", StringComparison.Ordinal))
                throw new ForbiddenException("This receipt does not belong to you.");
            if (!await receipts.ExistsAsync(cmd.ReceiptBlobName, ct))
                throw new DomainException("The receipt was not uploaded. Please upload it again.");

            expense = Expense.Submit(cmd.Id, userId, cmd.Amount, cmd.Currency, cmd.Category, cmd.Description,
                cmd.ExpenseDate, cmd.ReceiptBlobName, clock.UtcNow);
            db.Expenses.Add(expense);
            await db.SaveChangesAsync(ct);
        }

        // Start the workflow exactly once. If an earlier attempt saved the expense but failed here, the retry repairs it.
        if (expense.WorkflowInstanceId is null)
        {
            var instanceId = await workflows.StartApprovalAsync(expense.Id, ct);
            expense.AttachWorkflow(instanceId);
            await db.SaveChangesAsync(ct);
        }

        return await db.Expenses.AsNoTracking().Where(e => e.Id == expense.Id)
            .Select(ExpenseMapping.ToSummary).FirstAsync(ct);
    }
}
